import type { Metadata } from "next";
import Navbar from "../components/layout/navbar";
import "@styles/theme/main.global.css";
import "@styles/dist/main.global.css";
import "@styles/theme/theme.style.css"
// import { ReactLenis } from "@utils/react-lenis";
import PathChecker from "@lib/page-path-checker";
import 'boxicons/css/boxicons.min.css';
import { AuthProvider } from "@providers/AuthProvider"
import { ThemeProvider } from "@providers/ThemeProvider";
import SideBar from "@components/layout/sidecart";

export const metadata: Metadata = {
  title: "WoahGPT",
  icons: {
    icon: "/favicon.ico",
  },
  description: "By Barlon Corporation.",
};

export default async function RootLayout({
  children,
}: Readonly<{
  children: React.ReactNode;
}>) {
    return (
    <html lang="en">
      <ThemeProvider>
      <AuthProvider>
        <body className={`app-layout`}>
          {/* <ReactLenis root options={{
            lerp: 0.1,
            touchMultiplier: 1.25,
          }} > */}
            <main className="main-layout">
              <PathChecker />
              <section className="layout-elements">
                <nav className="navigation-bar">
                  <Navbar />
                </nav>
                <section className="app-page-view flex">
                  <aside><SideBar /></aside>
                  {children}
                </section>
              </section>
            </main>
          {/* </ReactLenis> */}
        </body>
      </AuthProvider>
      </ThemeProvider>
    </html>
  );
}
